 item=next(i for i in source['items'] if i['id'].startswith(prefix));index=len(observations)
 o=dict(matter=matter,matter_id=None,owner=None,due_text=None,condition_text=None,update_target=None,update='none',commitment_strength='not_applicable',work_state='not_applicable',state_evidence_ids=[],uncertainty=None,action_uncertainty=None,required_review=False,kind=kind,title=title,claim=claim,evidence_ids=[f'U{n:04d}' for n in lines]);o.update(extra)
